package com.finalanswer.server.game.systembreach;

import com.erni.finalanswer.gameplay.systembreach.*;
import com.google.gson.*;
import org.junit.jupiter.api.Test;
import java.lang.reflect.Field;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.erni.finalanswer.gameplay.systembreach.SystemBreachConfig.Parameter.*;

class SystemBreachSessionTest {
    final Gson json=new Gson();
    static class F {
        long now=100000;int request;final SystemBreachConfig cfg;final SystemBreachSession s;Set<String> online=new HashSet<>(List.of("a","b"));
        F(){this(new SystemBreachConfig().with(INITIAL_AP,200));}
        F(SystemBreachConfig cfg){this.cfg=cfg;s=new SystemBreachSession(List.of("a","b"),now,cfg,new Random(42),2);}
        SystemBreachSession.ActionResult act(String who,String action,Map<String,?> fields){return named(who,"r"+(++request),action,fields);}
        SystemBreachSession.ActionResult named(String who,String request,String action,Map<String,?> fields){return s.act(who,request,action,new Gson().toJsonTree(fields).getAsJsonObject(),now,online);}
        void active(){for(String id:List.of("a","b"))act(id,"PASSWORD_SELECT",Map.of("password",p(id).passwordOptions.getFirst()));}
        @SuppressWarnings("unchecked") SystemBreachPlayerState p(String id){try{Field f=SystemBreachSession.class.getDeclaredField("players");f.setAccessible(true);return ((Map<String,SystemBreachPlayerState>)f.get(s)).get(id);}catch(Exception e){throw new AssertionError(e);}}
        void advance(long ms){now+=ms;s.tick(now,online);}
        Map<String,Object> view(String id){return s.snapshot(id,id.equals("host"),now,online,Map.of("a","Alpha","b","Beta"));}
        BreachChallenge challenge(String id,ChallengeType type){act(id,"CHALLENGE_REQUEST",Map.of("type",type.name()));return p(id).challenge;}
        void attack(){act("a","ATTACK_REQUEST",Map.of("targetId","b"));}
        void breach(){attack();act("a","ATTACK_SUBMIT",Map.of("attackId",p("a").attack.id,"password",p("b").password));}
        void recover(){var c=p("b").recovery;if(c.cooling()){act("b","RECOVERY_SUBMIT",Map.of("challengeId",c.id,"answer",Map.of("level",3)));advance(5000);}else act("b","RECOVERY_SUBMIT",Map.of("challengeId",c.id,"answer",c.solution));}
    }
    static void failure(String code,Runnable call){assertEquals("SB_"+code,assertThrows(BreachFailure.class,call::run).getMessage());}
    @Test void rosterAndConfigurationAreValidated(){for(int count:List.of(1,9))assertThrows(BreachFailure.class,()->new SystemBreachSession(java.util.stream.IntStream.range(0,count).mapToObj(Integer::toString).toList(),0,new SystemBreachConfig(),new Random(),1));assertThrows(BreachFailure.class,()->new SystemBreachSession(List.of("a","a"),0,new SystemBreachConfig(),new Random(),1));assertThrows(IllegalArgumentException.class,()->new SystemBreachConfig().with(ATTACK_COST,-1));}
    @Test void initializesIndependentlyAndWaitsForPasswords(){var f=new F(new SystemBreachConfig());assertEquals(0,f.p("a").ap());assertEquals(1,f.p("a").firewall);assertEquals(100,f.p("a").integrity);assertEquals(SystemBreachPhase.INITIALIZATION,f.s.phase());failure("INVALID_ACTION",()->f.act("a","PASSWORD_SELECT",Map.of("password","NOT_AN_OPTION")));f.act("a","PASSWORD_SELECT",Map.of("password",f.p("a").passwordOptions.getFirst()));assertEquals(SystemBreachPhase.INITIALIZATION,f.s.phase());failure("PASSWORD_ALREADY_SELECTED",()->f.act("a","PASSWORD_SELECT",Map.of("password","DARK")));f.advance(f.cfg.get(INITIALIZATION_MS));assertEquals(SystemBreachPhase.ACTIVE,f.s.phase());assertNotNull(f.p("b").password);}
    @Test void allSelectedStartsEarlyAndActionsRequireActive(){var f=new F();failure("NOT_ACTIVE",()->f.challenge("a",ChallengeType.DATA_ANALYSIS));f.active();assertEquals(SystemBreachPhase.ACTIVE,f.s.phase());failure("INITIALIZATION_CLOSED",()->f.act("a","PASSWORD_SELECT",Map.of("password","DARK")));}
    @Test void allTenGeneratorsProduceValidSolvableVariants(){var cfg=new SystemBreachConfig();var factory=new ChallengeFactory(new Random(17),cfg,3);for(int i=0;i<100;i++){
        for(var type:ChallengeType.values()){var c=factory.earning(type,10000);JsonElement answer=c.solution;long at=10001;
            if(type==ChallengeType.CIRCUIT_BYPASS){JsonArray turns=new JsonArray();@SuppressWarnings("unchecked") var nodes=(List<Map<String,Object>>)c.data.get("nodes");for(int n=0;n<nodes.size();n++){int initial=((Number)nodes.get(n).get("connections")).intValue(),expected=c.solution.getAsJsonArray().get(n).getAsInt(),rotation=0;while(rotation<4&&ChallengeFactory.rotate(initial,rotation)!=expected)rotation++;assertTrue(rotation<4);turns.add(rotation);}answer=turns;}
            if(type==ChallengeType.SIGNAL_INTERCEPTION){at=((Number)c.data.get("windowOpensAt")).longValue();answer=new JsonObject();}assertTrue(c.validate(answer,at),type.name());assertFalse(c.validate(answer,c.expires));assertFalse(new Gson().toJson(c.view(at)).contains("solution"));
        }
        for(var type:RecoveryType.values()){var c=factory.recovery(type,10000);if(c.cooling()){assertFalse(c.validate(JsonParser.parseString("{\"level\":3}"),10001));assertTrue(c.cooled(15000));}else assertTrue(c.validate(c.solution,10001),type.name());}
    }}
    @Test void zeroAPCanEarnAndPayForAttack(){var f=new F(new SystemBreachConfig());f.active();for(int i=0;i<2;i++){var c=f.challenge("a",ChallengeType.DATA_ANALYSIS);f.act("a","CHALLENGE_SUBMIT",Map.of("challengeId",c.id,"answer",c.solution));f.advance(1000);}assertEquals(30,f.p("a").ap());f.attack();assertEquals(15,f.p("a").ap());}
    @Test void duplicateRewardCannotBeClaimedWithSameOrNewRequest(){var f=new F();f.active();var c=f.challenge("a",ChallengeType.PASSWORD_DECRYPTION);int before=f.p("a").ap();var payload=Map.of("challengeId",c.id,"answer",c.solution);var first=f.named("a","fixed","CHALLENGE_SUBMIT",payload);assertEquals(first,f.named("a","fixed","CHALLENGE_SUBMIT",payload));assertEquals(before+10,f.p("a").ap());failure("STALE_CHALLENGE",()->f.act("a","CHALLENGE_SUBMIT",payload));}
    @Test void challengeExpirationAndIncorrectAnswersNeverReward(){var f=new F();f.active();var c=f.challenge("a",ChallengeType.PASSWORD_DECRYPTION);int ap=f.p("a").ap();f.act("a","CHALLENGE_SUBMIT",Map.of("challengeId",c.id,"answer","WRONG"));assertEquals(ap,f.p("a").ap());f.advance(1000);c=f.challenge("a",ChallengeType.PORT_DETECTION);var id=c.id;f.advance(f.cfg.get(CHALLENGE_MS));failure("STALE_CHALLENGE",()->f.act("a","CHALLENGE_SUBMIT",Map.of("challengeId",id,"answer",0)));}
    @Test void signalUsesArrivalTimeAndRejectsFakeTimestamp(){var f=new F();f.active();var c=f.challenge("a",ChallengeType.SIGNAL_INTERCEPTION);assertFalse(c.validate(new JsonObject(),f.now));assertThrows(BreachFailure.class,()->c.validate(JsonParser.parseString("{\"clientAt\":999999}"),f.now));long opens=((Number)c.data.get("windowOpensAt")).longValue();assertTrue(c.validate(new JsonObject(),opens-f.cfg.get(SIGNAL_TOLERANCE_MS)));assertFalse(c.validate(new JsonObject(),opens-f.cfg.get(SIGNAL_TOLERANCE_MS)-1));}
    @Test void successfulAttackTransfersAPRotatesPasswordAndStartsRecovery(){var f=new F();f.active();String password=f.p("b").password;f.breach();assertEquals(205,f.p("a").ap());assertEquals(180,f.p("b").ap());assertTrue(f.p("b").compromised);assertEquals(75,f.p("b").integrity);assertEquals(20,f.p("b").infection);assertNotEquals(password,f.p("b").password);assertNotNull(f.p("b").recovery);failure("RECOVERY_REQUIRED",()->f.act("b","ATTACK_REQUEST",Map.of("targetId","a")));f.recover();assertFalse(f.p("b").compromised);assertEquals(100,f.p("b").integrity);assertEquals(0,f.p("b").infection);}
    @Test void failedAttackChargesPenaltyAndCooldown(){var f=new F();f.active();f.attack();String wrong=f.p("a").attack.options.stream().filter(s->!s.equals(f.p("b").password)).findFirst().orElseThrow();f.act("a","ATTACK_SUBMIT",Map.of("attackId",f.p("a").attack.id,"password",wrong));assertEquals(180,f.p("a").ap());assertFalse(f.p("b").compromised);failure("ATTACK_COOLDOWN",f::attack);}
    @Test void rejectsSelfDisconnectedConcurrentAndReplayedAttacks(){var f=new F();f.active();failure("SELF_ATTACK",()->f.act("a","ATTACK_REQUEST",Map.of("targetId","a")));f.online.remove("b");failure("TARGET_DISCONNECTED",f::attack);f.online.add("b");f.attack();failure("ATTACK_PENDING",f::attack);String old=f.p("a").attack.id;f.advance(f.cfg.get(ATTACK_GUESS_MS));assertNull(f.p("a").attack);failure("STALE_ATTACK",()->f.act("a","ATTACK_SUBMIT",Map.of("attackId",old,"password","DARK")));}
    @Test void firewallChargesOncePerLevelAndProtectsCurrency(){var f=new F();f.active();f.act("b","FIREWALL_UPGRADE",Map.of());f.act("b","FIREWALL_UPGRADE",Map.of());assertEquals(110,f.p("b").ap());assertEquals(3,f.p("b").firewall);failure("MAX_FIREWALL",()->f.act("b","FIREWALL_UPGRADE",Map.of()));f.breach();assertEquals(185,f.p("a").ap());assertEquals(100,f.p("b").ap());}
    @Test void allSpecialAttacksApplyAndExpire(){for(var type:SpecialAttackType.values()){var f=new F();f.active();if(type==SpecialAttackType.FIREWALL_BREAKER)f.act("b","FIREWALL_UPGRADE",Map.of());f.act("a","SPECIAL_ATTACK",Map.of("type",type.name(),"targetId","b"));assertTrue(f.p("a").ap()<=200-f.cfg.cost(type)+f.cfg.get(DATA_LEAK_AMOUNT));switch(type){case TROJAN->{failure("TEMPORARILY_BLOCKED",()->f.challenge("b",ChallengeType.DATA_ANALYSIS));f.advance(f.cfg.get(TROJAN_MS));assertFalse(f.p("b").blocked(f.now));}case DATA_LEAK->assertEquals(185,f.p("b").ap());case SYSTEM_OVERLOAD->assertTrue(f.p("b").compromised);case FIREWALL_BREAKER->{assertEquals(1,f.p("b").effectiveFirewall(f.now));f.advance(f.cfg.get(BREAKER_MS));assertEquals(2,f.p("b").effectiveFirewall(f.now));}case TRACE_ATTACK->{assertFalse(f.p("a").trace.equals(f.p("b").password));assertTrue(f.p("a").trace.length()>0);f.advance(f.cfg.get(TRACE_MS));assertEquals("",f.p("a").trace);}}}}
    @Test void disruptionCannotStackAndCannotSpendTwice(){var f=new F();f.active();var fields=Map.of("type","TROJAN","targetId","b");f.named("a","special","SPECIAL_ATTACK",fields);int balance=f.p("a").ap();f.named("a","special","SPECIAL_ATTACK",fields);assertEquals(balance,f.p("a").ap());f.advance(f.cfg.get(SPECIAL_COOLDOWN_MS));assertFalse(f.p("b").disrupted(f.now));}
    @Test void recoveryFailuresReachEmergencyRestoreEvenOfflineAndCritical(){var f=new F(new SystemBreachConfig().with(INITIAL_AP,200).with(ATTACK_DAMAGE,100));f.active();f.breach();assertEquals(0,f.p("b").integrity);assertTrue(f.p("b").compromised);f.online.remove("b");f.advance(f.cfg.get(RECOVERY_MS)*f.cfg.get(RECOVERY_RETRIES)+1);assertFalse(f.p("b").compromised);assertEquals(100,f.p("b").integrity);f.online.add("b");assertNotNull(f.view("b").get("self"));}
    @Test void transfersAndPenaltiesNeverGoNegative(){var f=new F(new SystemBreachConfig().with(INITIAL_AP,15));f.active();f.attack();f.act("a","ATTACK_SUBMIT",Map.of("attackId",f.p("a").attack.id,"password",f.p("a").attack.options.stream().filter(w->!w.equals(f.p("b").password)).findFirst().orElseThrow()));assertEquals(0,f.p("a").ap());f.advance(16000);failure("INSUFFICIENT_AP",f::attack);}
    @Test void reconnectPreservesPendingAttemptAndRecoveryWithinTheirDeadlines(){var f=new F();f.active();f.attack();String pending=f.p("a").attack.id;f.online.remove("a");f.s.tick(f.now,f.online);assertEquals(pending,f.p("a").attack.id);f.online.add("a");f.advance(16000);assertNull(f.p("a").attack);f.breach();String recovery=f.p("b").recovery.id;f.online.remove("b");f.s.tick(f.now,f.online);f.online.add("b");assertEquals(recovery,f.p("b").recovery.id);assertTrue(f.view("b").toString().contains(recovery));}
    @Test void resultsAreDeterministicImmutableAndCleanupReleasesSecrets(){var f=new F();f.active();f.advance(f.cfg.get(GAME_MS));assertEquals(SystemBreachPhase.RESULTS,f.s.phase());var result=f.s.outcome(Map.of("a","A","b","B"));assertEquals("a",result.winnerId());assertEquals(1,result.rankings().getFirst().rank());failure("CLOSED",()->f.act("a","FIREWALL_UPGRADE",Map.of()));f.advance(f.cfg.get(RESULTS_MS));assertEquals(SystemBreachPhase.FINISHED,f.s.phase());assertNull(f.p("a").password);assertNull(f.p("b").recovery);assertEquals(result,f.s.outcome(Map.of("a","A","b","B")));f.s.close();assertFalse(f.view("a").containsKey("self"));}
    @Test void projectionsDoNotSerializePasswordsSolutionsOrPrivateState(){var f=new F();f.active();var c=f.challenge("a",ChallengeType.DATA_ANALYSIS);String host=new Gson().toJson(f.view("host")),other=new Gson().toJson(f.view("b"));assertFalse(host.contains(c.id));assertFalse(other.contains(c.id));assertFalse(host.contains("password"));assertFalse(host.contains("solution"));assertFalse(other.contains("secretPassword"));assertTrue(new Gson().toJson(f.view("a")).contains(c.id));}
    @Test void concurrentDuplicateRewardIsExactlyOnce()throws Exception{var f=new F();f.active();var c=f.challenge("a",ChallengeType.PASSWORD_DECRYPTION);int before=f.p("a").ap();var pool=Executors.newFixedThreadPool(8);try{var jobs=new ArrayList<Callable<Object>>();for(int i=0;i<8;i++)jobs.add(()->f.named("a","same","CHALLENGE_SUBMIT",Map.of("challengeId",c.id,"answer",c.solution)));for(var future:pool.invokeAll(jobs))future.get();assertEquals(before+10,f.p("a").ap());}finally{pool.shutdownNow();}}
    @Test void concurrentSpendingCannotOverspend()throws Exception{var f=new F(new SystemBreachConfig().with(INITIAL_AP,30));f.active();var pool=Executors.newFixedThreadPool(2);try{var jobs=List.<Callable<Boolean>>of(()->{try{f.named("a","upgrade1","FIREWALL_UPGRADE",Map.of());return true;}catch(BreachFailure e){return false;}},()->{try{f.named("a","upgrade2","FIREWALL_UPGRADE",Map.of());return true;}catch(BreachFailure e){return false;}});var futures=pool.invokeAll(jobs);assertNotEquals(futures.get(0).get(),futures.get(1).get());assertEquals(0,f.p("a").ap());assertEquals(2,f.p("a").firewall);}finally{pool.shutdownNow();}}
    @Test void allPlayersFromTwoToEightCanFinish(){for(int n=2;n<=8;n++){var ids=java.util.stream.IntStream.range(0,n).mapToObj(i->"p"+i).toList();var s=new SystemBreachSession(ids,0,new SystemBreachConfig(),new Random(n),1);s.tick(20000+240000+10000,new HashSet<>(ids));assertEquals(SystemBreachPhase.FINISHED,s.phase());assertEquals(n,s.outcome(Map.of()).rankings().size());}}
    @Test void breakerCanBeUsedForAnActualAttackAndDoesNotStackWithCompromise(){
        var f=new F();f.active();f.act("b","FIREWALL_UPGRADE",Map.of());f.act("a","SPECIAL_ATTACK",Map.of("type","FIREWALL_BREAKER","targetId","b"));
        int before=f.p("a").ap();f.attack();assertEquals(before-15,f.p("a").ap());f.act("a","ATTACK_SUBMIT",Map.of("attackId",f.p("a").attack.id,"password",f.p("b").password));
        assertTrue(f.p("b").compromised);assertNull(f.p("b").effect);assertEquals(150,f.p("b").ap());
    }
    @Test void traceRemainsUsableWhenRequestingAPasswordAttack(){var f=new F();f.active();f.act("a","SPECIAL_ATTACK",Map.of("type","TRACE_ATTACK","targetId","b"));f.attack();assertFalse(f.p("a").trace.isEmpty());assertNotNull(f.p("a").attack);}
    @Test void duplicatesRemainProtectedAfterManyOtherTransactions(){
        var cfg=new SystemBreachConfig().with(INITIAL_AP,10000).with(TRACE_COST,1).with(SPECIAL_COOLDOWN_MS,1).with(REQUESTS_PER_SECOND,20);var f=new F(cfg);f.active();
        var action=Map.of("type","TRACE_ATTACK","targetId","b");f.advance(1000);f.named("a","original","SPECIAL_ATTACK",action);
        for(int i=0;i<650;i++){f.advance(70);f.named("a","other"+i,"SPECIAL_ATTACK",action);}int balance=f.p("a").ap();f.named("a","original","SPECIAL_ATTACK",action);assertEquals(balance,f.p("a").ap());
    }
    @Test void twoAttackersCannotReserveTheSameVictimOrDoubleSpend()throws Exception{
        var ids=List.of("a","b","c");var cfg=new SystemBreachConfig().with(INITIAL_AP,30);var session=new SystemBreachSession(ids,0,cfg,new Random(7),1);Set<String> online=new HashSet<>(ids);session.tick(20000,online);
        var pool=Executors.newFixedThreadPool(2);try{var jobs=new ArrayList<Callable<Boolean>>();for(String id:List.of("a","b"))jobs.add(()->{try{session.act(id,id,"ATTACK_REQUEST",new Gson().toJsonTree(Map.of("targetId","c")).getAsJsonObject(),20001,online);return true;}catch(BreachFailure e){return false;}});var result=pool.invokeAll(jobs);assertNotEquals(result.get(0).get(),result.get(1).get());}finally{pool.shutdownNow();}
    }

    @Test void impossibleTimingOverridesAreRejectedInsteadOfGeneratingUnsolvablePuzzles(){
        assertThrows(IllegalArgumentException.class,()->new SystemBreachConfig().with(CHALLENGE_MS,3000));
        assertThrows(IllegalArgumentException.class,()->new SystemBreachConfig(Map.of(RECOVERY_MS,3000,COOLING_CONTROL_PER_SECOND,10,COOLING_PASSIVE_PER_SECOND,10,COOLING_START,100,COOLING_TARGET,20,COOLING_STABLE_MS,3000)));
    }
    @Test void challengeOwnershipAndForbiddenClientStateAreValidated(){var f=new F();f.active();var c=f.challenge("a",ChallengeType.DATA_ANALYSIS);failure("STALE_CHALLENGE",()->f.act("b","CHALLENGE_SUBMIT",Map.of("challengeId",c.id,"answer",c.solution)));failure("INVALID_ACTION",()->f.act("a","CHALLENGE_SUBMIT",Map.of("challengeId",c.id,"answer",c.solution,"reward",99999)));assertEquals(200,f.p("a").ap());}
    @Test void balanceCapPreservesTransferConservation(){var f=new F(new SystemBreachConfig().with(INITIAL_AP,10000).with(MAX_AP,10000));f.active();f.breach();assertEquals(10000,f.p("a").ap());assertEquals(9985,f.p("b").ap());}
    @Test void eachSpecialChargesExactlyItsConfiguredCost(){for(var type:SpecialAttackType.values()){var f=new F();f.active();f.act("a","SPECIAL_ATTACK",Map.of("type",type.name(),"targetId","b"));assertEquals(200-f.cfg.cost(type)+(type==SpecialAttackType.DATA_LEAK?f.cfg.get(DATA_LEAK_AMOUNT):0),f.p("a").ap());failure("ATTACK_COOLDOWN",()->f.act("a","SPECIAL_ATTACK",Map.of("type",type.name(),"targetId","b")));}}

}
